    '<tr data-fam="%s" data-grp="%s" data-ori="%s" data-con="%s" data-buscar="%s">
<td><a href="fichas/%s.html">%s</a></td><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>\n',
    esc(r$fam), esc(r$grp), esc(r$ori), esc(r$con), esc(buscar),
    esc(r$slug), esc(r$nombre_mostrar), sci_html(r$sci, r$aut), esc(r$fam), esc(r$grp), esc(r$ori), r$con_html
  ))
}

cat('</tbody></table>
</div>

<script>
(function(){
  var q=document.getElementById("cat-q"),
      ff=document.getElementById("cat-fam"),
      fg=document.getElementById("cat-grp"),
      fo=document.getElementById("cat-ori"),
      fc=document.getElementById("cat-con"),
      filas=document.querySelectorAll("#cat-tabla tbody tr"),
      conteo=document.getElementById("cat-conteo");
  function norm(s){return (s||"").toLowerCase();}
  function aplica(){
    var qs=norm(q.value), vf=ff.value, vg=fg.value, vo=fo.value, vc=fc.value, n=0;
    filas.forEach(function(tr){
      var ok = tr.dataset.buscar.indexOf(qs)>=0 &&
               (!vf || tr.dataset.fam===vf) &&
               (!vg || tr.dataset.grp===vg) &&
               (!vo || tr.dataset.ori===vo) &&
               (!vc || tr.dataset.con===vc);
      tr.style.display = ok ? "" : "none";
      if(ok) n++;
    });
    conteo.textContent = n + " de " + filas.length + " ejemplares";
  }
  [q,ff,fg,fo,fc].forEach(function(e){ e.addEventListener("input",aplica); e.addEventListener("change",aplica); });
  aplica();
})();
</script>')
